1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	import http from 'node:http';
3	import { readFile, writeFile } from 'node:fs/promises';
4	import path from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	
7	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
8	const MAX_BODY_BYTES = 10000;
9	const HOST = '127.0.0.1';
10	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
11	const JSON_TYPE = 'application/json; charset=utf-8';
12	const PAGE_FILES = Object.freeze({
13	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
14	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
15	});
16	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
17	const BOOKINGS_PREFIX = '/api/bookings/';
18	
19	class HttpError extends Error {
20	  constructor(status, message) {
21	    super(message);
22	    this.status = status;
23	  }
24	}
25	
26	// ---------- field validation (shared by requests and the data file) ----------
27	
28	function isValidDate(value) {
29	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
30	  const year = Number(value.slice(0, 4));
31	  const month = Number(value.slice(5, 7));
32	  const day = Number(value.slice(8, 10));
33	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
34	  const febDays = year % 4 === 0 ? 29 : 28;
35	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
36	  return day <= monthDays[month - 1];
37	}
38	
39	function isValidTime(value) {
40	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
41	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
42	}
43	
44	function isValidTitle(value) {
45	  return typeof value === 'string' && value.length >= 1 && value.length <= 80;
46	}
47	
48	function isPlainObject(value) {
49	  return typeof value === 'object' && value !== null && !Array.isArray(value);
50	}
51	
52	function overlaps(a, b) {
53	  return a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
54	}
55	
56	// ---------- data file ----------
57	
58	function isStoredBooking(b, nextId) {
59	  if (!isPlainObject(b)) return false;
60	  const keys = Object.keys(b);
61	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => Object.hasOwn(b, k))) return false;
62	  return Number.isSafeInteger(b.id) && b.id >= 1 && b.id < nextId
63	    && ROOMS.includes(b.room)
64	    && isValidTitle(b.title) && b.title === b.title.trim()
65	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
66	}
67	
68	function hasConflicts(bookings) {
69	  const ids = new Set(bookings.map((b) => b.id));
70	  if (ids.size !== bookings.length) return true;
71	  return bookings.some((a, i) => bookings.slice(i + 1).some((b) => overlaps(a, b)));
72	}
73	
74	function parseStore(text) {
75	  const data = JSON.parse(text);
76	  const valid = isPlainObject(data)
77	    && Object.keys(data).length === 2
78	    && Number.isSafeInteger(data.nextId) && data.nextId >= 1
79	    && Array.isArray(data.bookings)
80	    && data.bookings.every((b) => isStoredBooking(b, data.nextId))
81	    && !hasConflicts(data.bookings);
82	  if (!valid) throw new Error('invalid data layout');
83	  return Object.freeze({ nextId: data.nextId, bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))) });
84	}
85	
86	async function loadStore(filePath) {
87	  try {
88	    return parseStore(await readFile(filePath, 'utf8'));
89	  } catch (err) {
90	    if (err && err.code === 'ENOENT') return Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
91	    throw err;
92	  }
93	}
94	
95	function serializeStore(store) {
96	  return `${JSON.stringify({ nextId: store.nextId, bookings: store.bookings }, null, 2)}\n`;
97	}
98	
99	// ---------- request helpers ----------
100	
101	function readBody(req, keep) {
102	  return new Promise((resolve, reject) => {
103	    const chunks = [];
104	    let received = 0;
105	    req.on('data', (chunk) => {
106	      received += chunk.length;
107	      if (keep && received <= MAX_BODY_BYTES) chunks.push(chunk);
108	    });
109	    req.on('end', () => resolve({ received, buffer: Buffer.concat(chunks) }));
110	    req.on('error', reject);
111	  });
112	}
113	
114	function mediaType(header) {
115	  if (typeof header !== 'string') return null;
116	  const semi = header.indexOf(';');
117	  const raw = semi === -1 ? header : header.slice(0, semi);
118	  return raw.replace(/^[ \t]+|[ \t]+$/g, '').replace(/[A-Z]/g, (c) => c.toLowerCase());
119	}
120	
121	function sendJson(res, status, payload) {
122	  const body = JSON.stringify(payload);
123	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
124	  res.end(body);
125	}
126	
127	function sendError(res, status, message) {
128	  sendJson(res, status, { error: message });
129	}
130	
131	function compareBookings(a, b) {
132	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
133	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
134	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
135	}
136	
137	// ---------- booking validation ----------
138	
139	function parseBookingBody(req, received, buffer) {
140	  if (mediaType(req.headers['content-type']) !== 'application/json') {
141	    throw new HttpError(415, 'content type must be application/json');
142	  }
143	  if (received > MAX_BODY_BYTES) throw new HttpError(413, 'body too large');
144	  let body;
145	  try {
146	    body = JSON.parse(buffer.toString('utf8'));
147	  } catch {
148	    body = null;
149	  }
150	  if (!isPlainObject(body)) throw new HttpError(400, 'body must be a JSON object');
151	  return body;
152	}
153	
154	function validateBooking(body) {
155	  const field = (key) => (Object.hasOwn(body, key) ? body[key] : undefined);
156	  const room = field('room');
157	  if (typeof room !== 'string' || !ROOMS.includes(room)) {
158	    throw new HttpError(400, `room must be one of ${ROOMS.join(', ')}`);
159	  }
160	  const rawTitle = field('title');
161	  const title = typeof rawTitle === 'string' ? rawTitle.trim() : rawTitle;
162	  if (!isValidTitle(title)) throw new HttpError(400, 'title must be 1 to 80 characters');
163	  const date = field('date');
164	  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
165	  const start = field('start');
166	  if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
167	  const end = field('end');
168	  if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
169	  if (end <= start) throw new HttpError(400, 'end must be after start');
170	  return { room, title, date, start, end };
171	}
172	
173	// ---------- app ----------
174	
175	function createApp(initialStore, dataPath) {
176	  let store = initialStore;
177	  let queue = Promise.resolve();
178	
179	  // Runs mutations one at a time; a failed task does not block later ones.
180	  function serialize(task) {
181	    const run = queue.then(task);
182	    queue = run.catch(() => {});
183	    return run;
184	  }
185	
186	  async function commit(next) {
187	    try {
188	      await writeFile(dataPath, serializeStore(next));
189	    } catch {
190	      throw new HttpError(500, 'internal error');
191	    }
192	    store = next;
193	  }
194	
195	  function createBooking(fields) {
196	    return serialize(async () => {
197	      const clash = store.bookings
198	        .filter((b) => overlaps(b, fields))
199	        .sort((a, b) => (a.start < b.start ? -1 : 1))[0];
200	      if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
201	      const booking = Object.freeze({ id: store.nextId, ...fields });
202	      await commit(Object.freeze({ nextId: store.nextId + 1, bookings: Object.freeze([...store.bookings, booking]) }));
203	      return booking;
204	    });
205	  }
206	
207	  function deleteBooking(idText) {
208	    return serialize(async () => {
209	      const found = /^[1-9][0-9]*$/.test(idText) && store.bookings.some((b) => String(b.id) === idText);
210	      if (!found) throw new HttpError(404, 'booking not found');
211	      const bookings = Object.freeze(store.bookings.filter((b) => String(b.id) !== idText));
212	      await commit(Object.freeze({ nextId: store.nextId, bookings }));
213	    });
214	  }
215	
216	  function listBookings(query) {
217	    const params = new URLSearchParams(query);
218	    let list = store.bookings;
219	    if (params.has('date')) {
220	      const date = params.get('date');
221	      if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
222	      list = list.filter((b) => b.date === date);
223	    }
224	    return [...list].sort(compareBookings);
225	  }
226	
227	  async function servePage(res, page) {
228	    const content = await readFile(path.join(PUBLIC_DIR, page.file));
229	    res.writeHead(200, { 'Content-Type': page.type, 'Content-Length': content.length });
230	    res.end(content);
231	  }
232	
233	  async function route(req, res) {
234	    const target = req.url;
235	    const q = target.indexOf('?');
236	    const pathname = q === -1 ? target : target.slice(0, q);
237	    const query = q === -1 ? '' : target.slice(q + 1);
238	    const method = req.method;
239	    const isPost = pathname === '/api/bookings' && method === 'POST';
240	    const { received, buffer } = await readBody(req, isPost);
241	
242	    if (Object.hasOwn(PAGE_FILES, pathname)) {
243	      if (method !== 'GET') throw new HttpError(405, 'method not allowed');
244	      return servePage(res, PAGE_FILES[pathname]);
245	    }
246	    if (pathname === '/api/rooms') {
247	      if (method !== 'GET') throw new HttpError(405, 'method not allowed');
248	      return sendJson(res, 200, { rooms: ROOMS });
249	    }
250	    if (pathname === '/api/bookings') {
251	      if (method === 'GET') return sendJson(res, 200, { bookings: listBookings(query) });
252	      if (!isPost) throw new HttpError(405, 'method not allowed');
253	      const fields = validateBooking(parseBookingBody(req, received, buffer));
254	      return sendJson(res, 201, await createBooking(fields));
255	    }
256	    if (pathname.startsWith(BOOKINGS_PREFIX)) {
257	      const idText = pathname.slice(BOOKINGS_PREFIX.length);
258	      if (idText === '' || idText.includes('/')) throw new HttpError(404, 'not found');
259	      if (method !== 'DELETE') throw new HttpError(405, 'method not allowed');
260	      await deleteBooking(idText);
261	      res.writeHead(204);
262	      return res.end();
263	    }
264	    throw new HttpError(404, 'not found');
265	  }
266	
267	  return async function handle(req, res) {
268	    try {
269	      await route(req, res);
270	    } catch (err) {
271	      if (res.headersSent) {
272	        res.destroy();
273	        return;
274	      }
275	      if (err instanceof HttpError) sendError(res, err.status, err.message);
276	      else sendError(res, 500, 'internal error');
277	    }
278	  };
279	}
280	
281	// ---------- startup ----------
282	
283	function fail(message) {
284	  process.stderr.write(`${message}\n`);
285	  process.exitCode = 1;
286	}
287	
288	function parsePort(raw) {
289	  if (raw === undefined || raw === '') return 3000;
290	  if (!/^[0-9]+$/.test(raw)) return null;
291	  const port = Number(raw);
292	  return port <= 65535 ? port : null;
293	}
294	
295	async function main() {
296	  const port = parsePort(process.env.PORT);
297	  if (port === null) return fail(`invalid PORT ${process.env.PORT}`);
298	
299	  const dataName = process.env.DATA_FILE || 'bookings.json';
300	  const dataPath = path.resolve(process.cwd(), dataName);
301	  let store;
302	  try {
303	    store = await loadStore(dataPath);
304	  } catch {
305	    return fail(`cannot read data file ${dataName}`);
306	  }
307	
308	  const server = http.createServer(createApp(store, dataPath));
309	  server.on('error', (err) => fail(`cannot listen on port ${port}: ${err.code || 'error'}`));
310	  server.listen(port, HOST, () => {
311	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
312	  });
313	}
314	
315	main();
316

1	'use strict';
2	
3	(function bookingPage() {
4	  const UNREACHABLE = 'Could not reach the server.';
5	  const FALLBACK_ERROR = 'Request failed.';
6	
7	  const form = document.getElementById('booking-form');
8	  const roomSelect = document.getElementById('room');
9	  const titleInput = document.getElementById('title');
10	  const dateInput = document.getElementById('date');
11	  const startInput = document.getElementById('start');
12	  const endInput = document.getElementById('end');
13	  const bookButton = document.getElementById('book');
14	  const filterDate = document.getElementById('filter-date');
15	  const showAllButton = document.getElementById('show-all');
16	  const bookingList = document.getElementById('booking-list');
17	  const errorBox = document.getElementById('error');
18	
19	  let listSequence = 0;
20	
21	  function showError(message) {
22	    errorBox.textContent = message;
23	  }
24	
25	  function clearError() {
26	    errorBox.textContent = '';
27	  }
28	
29	  function isPlainObject(value) {
30	    return typeof value === 'object' && value !== null && !Array.isArray(value);
31	  }
32	
33	  function errorMessage(data) {
34	    return isPlainObject(data) && typeof data.error === 'string' ? data.error : FALLBACK_ERROR;
35	  }
36	
37	  function buildOptions(method, payload) {
38	    if (payload === undefined) {
39	      return { method };
40	    }
41	    return {
42	      method,
43	      headers: { 'Content-Type': 'application/json' },
44	      body: JSON.stringify(payload),
45	    };
46	  }
47	
48	  // Resolves to { status, data } or to null when there was no usable reply.
49	  // onSettle runs as soon as the reply and its body have arrived, or the request failed.
50	  async function request(method, url, payload, onSettle) {
51	    const settle = typeof onSettle === 'function' ? onSettle : () => {};
52	    let response;
53	    try {
54	      response = await fetch(url, buildOptions(method, payload));
55	    } catch {
56	      settle();
57	      return null;
58	    }
59	    const status = response.status;
60	    if (status === 204) {
61	      settle();
62	      return { status, data: null };
63	    }
64	    let data;
65	    try {
66	      data = await response.json();
67	    } catch {
68	      settle();
69	      return null;
70	    }
71	    settle();
72	    return { status, data };
73	  }
74	
75	  function makeOption(name) {
76	    const option = document.createElement('option');
77	    option.value = String(name);
78	    option.textContent = String(name);
79	    return option;
80	  }
81	
82	  async function loadRooms() {
83	    const reply = await request('GET', '/api/rooms');
84	    if (reply === null) {
85	      showError(UNREACHABLE);
86	      return;
87	    }
88	    const rooms = isPlainObject(reply.data) ? reply.data.rooms : undefined;
89	    if (reply.status !== 200 || !Array.isArray(rooms)) {
90	      showError(errorMessage(reply.data));
91	      return;
92	    }
93	    roomSelect.replaceChildren(...rooms.map(makeOption));
94	  }
95	
96	  function bookingText(booking) {
97	    return `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`;
98	  }
99	
100	  function makeBookingItem(booking) {
101	    const item = document.createElement('li');
102	    const cancelButton = document.createElement('button');
103	    cancelButton.type = 'button';
104	    cancelButton.textContent = 'Cancel';
105	    cancelButton.addEventListener('click', () => {
106	      cancelBooking(booking.id, cancelButton);
107	    });
108	    item.append(bookingText(booking), cancelButton);
109	    return item;
110	  }
111	
112	  function renderList(bookings) {
113	    if (bookings.length === 0) {
114	      const empty = document.createElement('li');
115	      empty.append('No bookings.');
116	      bookingList.replaceChildren(empty);
117	      return;
118	    }
119	    bookingList.replaceChildren(...bookings.map(makeBookingItem));
120	  }
121	
122	  function isBookingArray(value) {
123	    return Array.isArray(value) && value.every(isPlainObject);
124	  }
125	
126	  async function loadList() {
127	    listSequence += 1;
128	    const sequence = listSequence;
129	    const filter = filterDate.value;
130	    const url = filter === '' ? '/api/bookings' : '/api/bookings?date=' + filter;
131	    const reply = await request('GET', url);
132	    if (sequence !== listSequence) {
133	      return;
134	    }
135	    if (reply === null) {
136	      showError(UNREACHABLE);
137	      return;
138	    }
139	    const bookings = isPlainObject(reply.data) ? reply.data.bookings : undefined;
140	    if (reply.status !== 200 || !isBookingArray(bookings)) {
141	      showError(errorMessage(reply.data));
142	      return;
143	    }
144	    renderList(bookings);
145	  }
146	
147	  async function submitBooking() {
148	    bookButton.disabled = true;
149	    const payload = {
150	      room: roomSelect.value,
151	      title: titleInput.value,
152	      date: dateInput.value,
153	      start: startInput.value,
154	      end: endInput.value,
155	    };
156	    const reply = await request('POST', '/api/bookings', payload, () => {
157	      bookButton.disabled = false;
158	    });
159	    if (reply === null) {
160	      showError(UNREACHABLE);
161	      return;
162	    }
163	    if (reply.status !== 201) {
164	      showError(errorMessage(reply.data));
165	      return;
166	    }
167	    titleInput.value = '';
168	    clearError();
169	    loadList();
170	  }
171	
172	  async function cancelBooking(id, cancelButton) {
173	    if (cancelButton.disabled) {
174	      return;
175	    }
176	    cancelButton.disabled = true;
177	    const reply = await request('DELETE', '/api/bookings/' + id, undefined, () => {
178	      cancelButton.disabled = false;
179	    });
180	    if (reply === null) {
181	      showError(UNREACHABLE);
182	      return;
183	    }
184	    if (reply.status === 204) {
185	      clearError();
186	    } else {
187	      showError(errorMessage(reply.data));
188	    }
189	    loadList();
190	  }
191	
192	  form.addEventListener('submit', (event) => {
193	    event.preventDefault();
194	    if (bookButton.disabled) {
195	      return;
196	    }
197	    submitBooking();
198	  });
199	
200	  filterDate.addEventListener('change', () => {
201	    loadList();
202	  });
203	
204	  showAllButton.addEventListener('click', () => {
205	    filterDate.value = '';
206	    loadList();
207	  });
208	
209	  loadRooms();
210	  loadList();
211	})();
