import { spawn } from 'node:child_process';
import net from 'node:net';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const SERVER = '/root/bench-runs/h4-daaee26c/server.mjs';
const results = [];
const check = (name, ok, info = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${ok ? '' : ' :: ' + info}`);

function start(env, cwd = os.tmpdir()) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [SERVER], { env: { ...process.env, ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; const m = out.match(/listening on http:\/\/127\.0\.0\.1:(\d+)\n/); if (m) resolve({ p, port: +m[1], get out() { return out; }, get err() { return err; } }); });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (code) => resolve({ p, code, out, err, exited: true }));
  });
}
function run(env, cwd) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [SERVER], { env: { ...process.env, ...env }, cwd: cwd || os.tmpdir() });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; });
    p.stderr.on('data', (d) => { err += d; });
    const t = setTimeout(() => p.kill(), 3000);
    p.on('exit', (code) => { clearTimeout(t); resolve({ code, out, err }); });
  });
}
function raw(port, data) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = Buffer.alloc(0);
    s.on('data', (d) => { buf = Buffer.concat([buf, d]); });
    s.on('error', () => {});
    s.on('close', () => resolve(buf.toString('latin1')));
    s.write(data);
    s.end();
  });
}
function parse(resp) {
  const [head, ...rest] = resp.split('\r\n\r\n');
  const status = +head.split(' ')[1];
  const headers = Object.fromEntries(head.split('\r\n').slice(1).map((l) => [l.slice(0, l.indexOf(':')).toLowerCase(), l.slice(l.indexOf(':') + 1).trim()]));
  const body = rest.join('\r\n\r\n');
  let json; try { json = JSON.parse(body); } catch {}
  return { status, headers, body, json };
}
async function req(port, method, target, { body, headers = {} } = {}) {
  const b = body === undefined ? Buffer.alloc(0) : Buffer.isBuffer(body) ? body : Buffer.from(body);
  let h = `${method} ${target} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n`;
  for (const [k, v] of Object.entries(headers)) h += `${k}: ${v}\r\n`;
  if (b.length || method === 'POST') h += `Content-Length: ${b.length}\r\n`;
  return parse(await raw(port, Buffer.concat([Buffer.from(h + '\r\n', 'latin1'), b])));
