import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'dbg-'));
const df = path.join(tmp, 'd.json');
function start() {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, ['/root/bench-runs/h4-daaee26c/server.mjs'], { env: { ...process.env, PORT: '0', DATA_FILE: df } });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; const m = out.match(/:(\d+)\n/); if (m) resolve({ p, port: +m[1] }); });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (c) => resolve({ exited: c, err }));
  });
}
const post = (port, o) => fetch(`http://127.0.0.1:${port}/api/bookings`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ room: 'Aurora', title: 't', date: '2026-01-01', start: '09:00', end: '10:00', ...o }) }).then(async (r) => [r.status, await r.text()]);
let s = await start();
console.log(await post(s.port, {}));
console.log('after post:', JSON.stringify(fs.readFileSync(df, 'utf8')));
console.log(await post(s.port, { title: 'x�', start: '11:00', end: '12:00' }));
console.log(await post(s.port, { title: 'y'.repeat(80), date: '2000-02-29', start: '00:00', end: '23:59' }));
console.log('after posts:', fs.readFileSync(df, 'utf8').length);
s.p.kill(); await new Promise((r) => s.p.on('exit', r));
console.log('after kill:', fs.readFileSync(df, 'utf8').length);
s = await start();
console.log('restart', s.exited, s.err);
s.p?.kill();

